<?php
declare(strict_types=1);
namespace Vendi\Inventory;
use PDO;use RuntimeException;
final class InventoryCountService{public function __construct(private PDO $db){}
 public function post(int $businessId,int $branchId,int $userId,array $items,?string $notes=null):int{if(!$items)throw new RuntimeException('Agrega productos al conteo.');$own=!$this->db->inTransaction();if($own)$this->db->beginTransaction();try{$q=$this->db->prepare("INSERT INTO inventory_counts(business_id,branch_id,user_id,status,notes,created_at) VALUES(?,?,?,'draft',?,NOW())");$q->execute([$businessId,$branchId,$userId,$notes]);$cid=(int)$this->db->lastInsertId();foreach($items as $x){$pid=(int)$x['product_id'];$vid=!empty($x['variant_id'])?(int)$x['variant_id']:null;$s=$this->db->prepare("SELECT quantity FROM inventory WHERE branch_id=? AND product_id=? FOR UPDATE");$s->execute([$branchId,$pid]);$sys=(float)($s->fetchColumn()?:0);$count=(float)$x['counted_qty'];$diff=$count-$sys;$this->db->prepare("INSERT INTO inventory_count_items(count_id,product_id,variant_id,system_qty,counted_qty,difference_qty,reason) VALUES(?,?,?,?,?,?,?)")->execute([$cid,$pid,$vid,$sys,$count,$diff,$x['reason']??null]);if(abs($diff)>0.000001){$this->db->prepare("UPDATE inventory SET quantity=? WHERE branch_id=? AND product_id=?")->execute([$count,$branchId,$pid]);$this->db->prepare("INSERT INTO stock_movements(business_id,branch_id,product_id,variant_id,type,quantity,reference_type,reference_id,user_id,created_at) VALUES(?,?,?,?, 'adjustment',?,'inventory_count',?,?,NOW())")->execute([$businessId,$branchId,$pid,$vid,$diff,$cid,$userId]);}}$this->db->prepare("UPDATE inventory_counts SET status='posted',posted_at=NOW() WHERE id=?")->execute([$cid]);if($own)$this->db->commit();return$cid;}catch(\Throwable $e){if($own&&$this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function lowStock(int $businessId,int $branchId):array{$q=$this->db->prepare("SELECT p.id,p.name,p.sku,i.quantity,p.min_stock,p.max_stock FROM products p LEFT JOIN inventory i ON i.product_id=p.id AND i.branch_id=? WHERE p.business_id=? AND p.min_stock IS NOT NULL AND COALESCE(i.quantity,0)<=p.min_stock ORDER BY (p.min_stock-COALESCE(i.quantity,0)) DESC,p.name");$q->execute([$branchId,$businessId]);return$q->fetchAll();}
}